import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/sum-diff-multiple.svg",x=JSON.parse('{"title":"奥数精讲：和差和倍问题（线段图的力量）","description":"掌握解决“和差”与“和倍”问题的核心公式，学会利用线段图直观分析数量关系，让复杂的应用题变得一目了然。","frontmatter":{"title":"奥数精讲：和差和倍问题（线段图的力量）","date":"2026-02-28T10:00:00.000Z","categories":["数学"],"tags":["和差问题","和倍问题","线段图"],"description":"掌握解决“和差”与“和倍”问题的核心公式，学会利用线段图直观分析数量关系，让复杂的应用题变得一目了然。"},"headers":[],"relativePath":"posts/primary-math-olympiad-sum-diff-multi.md","filePath":"posts/primary-math-olympiad-sum-diff-multi.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-sum-diff-multi.md"};function e(o,a,r,i,c,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="和差和倍问题-学会画图-难题不愁" tabindex="-1">和差和倍问题：学会画图，难题不愁 <a class="header-anchor" href="#和差和倍问题-学会画图-难题不愁" aria-label="Permalink to &quot;和差和倍问题：学会画图，难题不愁&quot;">​</a></h1><p>在奥数中，有一类题目给出了两个数的“和”以及它们之间的“差”或“倍数关系”。解决这类问题的终极武器就是——<strong>线段图</strong>。</p><hr><h2 id="一、-和差问题-已知和与差" tabindex="-1">一、 和差问题：已知和与差 <a class="header-anchor" href="#一、-和差问题-已知和与差" aria-label="Permalink to &quot;一、 和差问题：已知和与差&quot;">​</a></h2><p>和差问题的特点是：已知两个数量的和，以及两个数量的差，求这两个数量。</p><h3 id="【核心公式】" tabindex="-1">【核心公式】 <a class="header-anchor" href="#【核心公式】" aria-label="Permalink to &quot;【核心公式】&quot;">​</a></h3><ul><li><strong>(和 + 差) ÷ 2 = 较大数</strong></li><li><strong>(和 - 差) ÷ 2 = 较小数</strong></li></ul><h3 id="【示例-1】" tabindex="-1">【示例 1】 <a class="header-anchor" href="#【示例-1】" aria-label="Permalink to &quot;【示例 1】&quot;">​</a></h3><p><strong>题目：</strong> 甲乙两数之和是 20，差是 4。求甲乙两数各是多少？（假设甲 &gt; 乙）</p><p><img src="'+p+'" alt="和差问题图解"></p><p><strong>解析：</strong></p><ol><li>如果给乙补上差额 4，那么乙就和甲一样多了，此时总和变成 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>2</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">20 + 4 = 24</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span></span></span></span>。这是两个甲的和。</li><li>所以甲 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>2</mn><mn>4</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">= 24 \\div 2 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>。</li><li>乙 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>1</mn><mn>2</mn><mo>−</mo><mn>4</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">= 12 - 4 = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span>（或者用 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>−</mo><mn>1</mn><mn>2</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">20 - 12 = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span>）。</li></ol><hr><h2 id="二、-和倍问题-已知和与倍数" tabindex="-1">二、 和倍问题：已知和与倍数 <a class="header-anchor" href="#二、-和倍问题-已知和与倍数" aria-label="Permalink to &quot;二、 和倍问题：已知和与倍数&quot;">​</a></h2><p>和倍问题的特点是：已知两个数量的和，以及一个数量是另一个数量的几倍，求这两个数量。</p><h3 id="【核心公式】-1" tabindex="-1">【核心公式】 <a class="header-anchor" href="#【核心公式】-1" aria-label="Permalink to &quot;【核心公式】&quot;">​</a></h3><ul><li><strong>和 ÷ (倍数 + 1) = 1 份量（较小数）</strong></li><li><strong>1 份量 × 倍数 = 较大数</strong></li></ul><h3 id="【示例-2】" tabindex="-1">【示例 2】 <a class="header-anchor" href="#【示例-2】" aria-label="Permalink to &quot;【示例 2】&quot;">​</a></h3><p><strong>题目：</strong> 哥哥和弟弟共有 20 本书，哥哥的书是弟弟的 3 倍。求哥哥和弟弟各有多少本书？</p><p><strong>解析：</strong></p><ol><li>弟弟的书是“1 份”，哥哥的书就是“3 份”。</li><li>两人合起来就是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">1 + 3 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span> 份。</li><li>对应的总数是 20 本。</li><li>每份是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>÷</mo><mn>4</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">20 \\div 4 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 本。这也就是弟弟的书。</li><li>哥哥的书 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>5</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>1</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">= 5 \\times 3 = 15</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span></span></span></span> 本。</li></ol><hr><h2 id="三、-引导性思考-如何举一反三" tabindex="-1">三、 引导性思考：如何举一反三？ <a class="header-anchor" href="#三、-引导性思考-如何举一反三" aria-label="Permalink to &quot;三、 引导性思考：如何举一反三？&quot;">​</a></h2><p>解决此类问题时，关键在于“转化”：</p><ol><li><strong>统一单位：</strong> 在倍数问题中，总是把那个“1 倍量”（通常是较小数）看作 1 份。</li><li><strong>动态平衡：</strong> 如果题目没直接给和，而是说“甲给了乙 5 个后两人一样多”，这说明原来的差是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">5 \\times 2 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>。</li></ol><hr><h2 id="四、-引申思考-如果是-差倍-问题呢" tabindex="-1">四、 引申思考：如果是“差倍”问题呢？ <a class="header-anchor" href="#四、-引申思考-如果是-差倍-问题呢" aria-label="Permalink to &quot;四、 引申思考：如果是“差倍”问题呢？&quot;">​</a></h2><p>如果已知两个数的“差”和“倍数关系”，公式会变成什么样？</p><ul><li><strong>差 ÷ (倍数 - 1) = 1 份量（较小数）</strong></li><li><em>思考：为什么是减 1？因为大数比小数多出的那部分，正好是 (倍数-1) 份。</em></li></ul><hr><h2 id="五、-举一反三-实战练习" tabindex="-1">五、 举一反三：实战练习 <a class="header-anchor" href="#五、-举一反三-实战练习" aria-label="Permalink to &quot;五、 举一反三：实战练习&quot;">​</a></h2><ol><li><p><strong>基础练习（和差）：</strong> 小明和小红共有 30 元钱，小明比小红多 6 元。两人各有多少钱？ <em>提示：(30 + 6) ÷ 2。</em></p></li><li><p><strong>进阶练习（和倍）：</strong> 果园里有桃树和梨树共 120 棵，桃树的棵数是梨树的 5 倍。桃树和梨树各有多少棵？ <em>提示：120 ÷ (5 + 1)。</em></p></li><li><p><strong>挑战练习（综合）：</strong> 甲乙两筐苹果共 60 斤，如果从甲筐取出 5 斤放入乙筐，则甲筐还比乙筐多 4 斤。原来两筐各有多少斤？ <em>提示：甲给了乙 5 斤还多 4 斤，说明原来甲比乙多 5 + 5 + 4 = 14 斤。</em></p></li></ol><hr><p><strong>解析预览：</strong></p><ol><li>小明：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>3</mn><mn>0</mn><mo>+</mo><mn>6</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">(30+6)\\div 2 = 18</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">8</span></span></span></span> 元；小红：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>8</mn><mo>−</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">18-6 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">8</span><span class="mbin">−</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span> 元。</li><li>梨树：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>0</mn><mo>÷</mo><mn>6</mn><mo>=</mo><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">120\\div 6 = 20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span> 棵；桃树：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 \\times 5 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span> 棵。</li><li>差 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>1</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">= 14</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span></span></span></span>，和 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>6</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">= 60</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span></span></span></span>。甲：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>6</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>4</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>3</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">(60+14)\\div 2 = 37</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span></span></span></span> 斤；乙：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mn>0</mn><mo>−</mo><mn>3</mn><mn>7</mn><mo>=</mo><mn>2</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">60-37 = 23</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span></span></span></span> 斤。</li></ol>',35)])])}const u=s(l,[["render",e]]);export{x as __pageData,u as default};
